const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=new Intl.DateTimeFormat('en-US',{timeZone:NookRank.ZONE,hour:'numeric',minute:'2-digit'}),day=new Intl.DateTimeFormat('en-US',{timeZone:NookRank.ZONE,weekday:'short',month:'short',day:'numeric'});
const kinds={library:'Library',cafe:'Café'},intents={focus:'Deep focus',group:'Group work',creative:'Creative flow',casual:'Light work'};
const labels={fits:'Listed hours fit',unknown:'Hours unconfirmed',outside:'Outside listed hours'};
let dataset,session,ranked=[],goal='focus',savedView=false,limit=6,current,toastTimer;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let saved=read('nook-osm-saved',[]),feedback=read('nook-osm-feedback',{});if(!Array.isArray(saved))saved=[];if(!feedback||typeof feedback!=='object')feedback={};
function write(){try{localStorage.setItem('nook-osm-saved',JSON.stringify(saved));localStorage.setItem('nook-osm-feedback',JSON.stringify(feedback))}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.opacity=0,2300)}
function wifi(v){return v.wifi.split(';').includes('wlan')}
function map(v){return 'https://www.openstreetmap.org/'+v.id}
function distance(d){return d<1000?d+' m':(d/1000).toFixed(1)+' km'}
function reason(r){const v=r.v;if(v.kind==='library'&&goal==='focus')return 'A library pick for focused work. Check visitor access before heading over.';if(v.kind==='cafe'&&goal==='group')return 'A café pick for conversation. Group seating is not confirmed.';if(v.kind==='cafe'&&goal==='creative')return 'A nearby café for a change of scene.';if(v.kind==='cafe'&&goal==='casual')return 'A café option for a short work session.';return 'An alternative nearby if a '+kinds[v.kind].toLowerCase()+' suits your plans.'}
function timeText(){return day.format(session.start)+' · '+fmt.format(session.start)+'–'+fmt.format(session.end)+' PT'}
function refresh(){if(!dataset)return;session=NookRank.plan($('#when').value,Number($('#duration').value));ranked=dataset.places.filter(v=>!['private','no'].includes(v.access)).map(v=>NookRank.evaluate(v,goal,NookRank.coverage(v.hours,session),Number(feedback[goal+v.id])||0)).filter(r=>r.d<=Number($('#distance').value)&&r.coverage!=='outside'&&(!$('#hoursOnly').checked||r.coverage==='fits')&&(!$('#wifiOnly').checked||wifi(r.v))&&(!savedView||saved.includes(r.v.id))).sort((a,b)=>b.score-a.score||a.d-b.d||a.v.name.localeCompare(b.v.name));render()}
function render(){ $('#saveCount').textContent=saved.length;$('#discover').classList.toggle('active',!savedView);$('#saved').classList.toggle('active',savedView);$('#title').textContent=savedView?'Your saved spaces.':intents[goal]+' shortlist.';$('#summary').textContent=timeText();$('#count').textContent=ranked.length+' match'+(ranked.length===1?'':'es');
$('#cards').innerHTML=ranked.slice(0,limit).map((r,i)=>{const v=r.v;return '<article class="card real"><div class="body"><div class="place-top"><span class="pill">'+(v.kind==='library'?'▤':'☕')+' &nbsp; '+kinds[v.kind]+'</span><button class="heart" aria-label="'+(saved.includes(v.id)?'Unsave':'Save')+' '+esc(v.name)+'" aria-pressed="'+saved.includes(v.id)+'" data-save="'+v.id+'">'+(saved.includes(v.id)?'♥':'♡')+'</button></div><h3>'+esc(v.name)+'</h3><div class="sub">'+distance(r.d)+' from Sather Gate · straight line</div><p class="reason">'+reason(r)+'</p><div class="amenities"><span>'+labels[r.coverage]+'</span>'+(wifi(v)?'<span>Mapped Wi-Fi</span>':'')+'</div><button class="view" data-view="'+v.id+'">View place <span>↗</span></button></div></article>'}).join('')||(savedView&&!saved.length?'<div class="empty"><h3>No saved spaces yet.</h3><p>Tap a heart on Discover to save a real place.</p></div>':'<div class="empty"><h3>No places match this session.</h3><p>Try tomorrow morning, a wider radius, or turn off the hours and Wi-Fi filters.</p></div>');
if(ranked.length>limit)$('#cards').insertAdjacentHTML('beforeend','<button class="view more" id="more">Show more places ↓</button>')}
function show(html){$('#detailContent').innerHTML=html;if(!$('#detail').open)$('#detail').showModal()}
function detail(r){current=r;window.nookTrack?.('place_viewed',{place_id:r.v.id,place_type:r.v.kind,intent:goal});const v=r.v;show('<div class="eyebrow">'+kinds[v.kind].toUpperCase()+' · OPENSTREETMAP</div><h2>'+esc(v.name)+'</h2><p>'+esc(v.address||'Street address not mapped')+'<br>'+distance(r.d)+' straight-line from Sather Gate</p><b>Why this match?</b><p>'+reason(r)+' '+labels[r.coverage]+' for '+timeText()+'.</p><div class="fact"><b>Listed hours</b><span>'+esc(v.hours||'Not mapped')+'</span></div><div class="fact"><b>Wi-Fi</b><span>'+(wifi(v)?'Wireless access listed':v.wifi==='no'?'Internet access listed as unavailable':'Not confirmed')+'</span></div><div class="fact"><b>Visitor access</b><span>'+esc(v.access||'Not confirmed')+'</span></div><p class="fine">Seats, outlets and noise are not verified. Listed hours can change; check with the venue before traveling.</p><a class="primary maplink" href="'+map(v)+'" target="_blank" rel="noopener">Open place on OpenStreetMap ↗</a><button id="feedbackBtn" class="view">Visited? Rate the fit</button>')}
function how(){show('<div class="eyebrow">FIELD NOTES</div><h2>Where your matches come from.</h2><p>Nook imports named cafés and libraries within 1.5 km of Sather Gate using the Overpass API. The app reads a saved snapshot, not a live crowd feed.</p><p>For deep focus, Nook favors libraries. For the other intents, it favors cafés. Venue type is a suggestion, not evidence of noise levels or available tables.</p><p>Type match and a session covered by listed hours each add 35 points. Proximity adds up to 30, and your feedback adjusts the result for the same intent. Distances are straight-line, not walking routes.</p><p>Unknown or complex schedules stay unconfirmed. Places known to close before your session ends are excluded. We don’t predict seats, measure Wi-Fi speed, or reserve tables.</p><p class="fine">'+esc($('#asOf').textContent)+' · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors · ODbL</a></p>')}
$('#cards').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='more'){limit+=6;render();return}if(b.dataset.save){const id=b.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];write();window.nookTrack?.(saved.includes(id)?'place_saved':'place_unsaved',{place_id:id,intent:goal});refresh()}else if(b.dataset.view)detail(ranked.find(r=>r.v.id===b.dataset.view))};
$('#detailContent').onclick=e=>{if(e.target.id==='feedbackBtn'){show('<div class="eyebrow">YOUR VISIT</div><h2>Did '+esc(current.v.name)+' work for you?</h2><p>Your answer adjusts future '+intents[goal].toLowerCase()+' matches on this device.</p><div class="feedback"><button data-rate="5">Good fit</button><button data-rate="-5">Poor fit</button></div>')}else if(e.target.dataset.rate){feedback[goal+current.v.id]=Number(e.target.dataset.rate);write();$('#detail').close();refresh();toast('Fit preference saved.')}}
document.querySelectorAll('[data-goal]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.goal===goal);b.onclick=()=>{goal=b.dataset.goal;window.nookTrack?.('intent_selected',{intent:goal});document.querySelectorAll('[data-goal]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});limit=6;refresh()}});
['when','duration','distance','hoursOnly','wifiOnly'].forEach(id=>$('#'+id).onchange=()=>{limit=6;refresh()});$('#find').onclick=()=>{savedView=false;limit=6;refresh();if(dataset)window.nookTrack?.('search_submitted',{intent:goal,duration_hours:Number($('#duration').value),start_option:$('#when').value,radius_m:Number($('#distance').value),hours_filter:$('#hoursOnly').checked,wifi_filter:$('#wifiOnly').checked,result_count:ranked.length});$('#results').scrollIntoView()};$('#saved').onclick=()=>{savedView=true;limit=6;refresh();$('#results').scrollIntoView()};$('#discover').onclick=()=>{savedView=false;refresh();$('.app-scroll').scrollTo({top:0})};$('#how').onclick=how;$('#close').onclick=()=>$('#detail').close();
async function init(){try{dataset=window.NOOK_SNAPSHOT||(await (await fetch('places.json')).json());if(!dataset.places?.length)throw Error('No data');$('#asOf').textContent='Map snapshot: '+new Intl.DateTimeFormat('en-US',{timeZone:NookRank.ZONE,dateStyle:'medium'}).format(new Date(dataset.asOf));refresh()}catch{$('#cards').innerHTML='<div class="empty"><h3>Places couldn’t load.</h3><p>Reload to try again.</p></div>'}}init();

$('#detailContent').addEventListener('click',e=>{if(e.target.closest('.maplink')&&current)window.nookTrack?.('map_link_clicked',{place_id:current.v.id,place_type:current.v.kind,intent:goal})});
$('#analyticsToggle').textContent=window.nookAnalyticsDisabled?.()?'Analytics off':'Turn analytics off';
$('#analyticsToggle').onclick=()=>window.nookToggleAnalytics?.();
